/// <summary>
/// Extension of SalesTable datasource on ReturnTableListPage form.
/// </summary>
[ExtensionOf(formDataSourceStr(ReturnTableListPage, SalesTable))]
final class METReturnTableListPageSalesTable_Extension
{
}

Method.Source:
/// <summary>
/// Restrict Return Orders by user restricted warehouses
/// </summary>
public void init()
{
    next init();

    QueryBuildDataSource salesTableDS = this.query().dataSourceTable(tableNum(SalesTable));

    if (salesTableDS && !Global::isSystemAdministrator())
    {
        QueryBuildDataSource warehouseListDS = salesTableDS.addDataSource(tableNum(METUserSecurityWarehouseList));
        warehouseListDS.joinMode(JoinMode::NoExistsJoin);
        warehouseListDS.relations(false);
        warehouseListDS.addLink(fieldNum(SalesTable, InventLocationId), fieldNum(METUserSecurityWarehouseList, InventLocationId));
        warehouseListDS.addLink(fieldNum(SalesTable, dataAreaId), fieldNum(METUserSecurityWarehouseList, Company));
        warehouseListDS.addRange(fieldNum(METUserSecurityWarehouseList, RestrictAllReturnOrders)).value(queryValue(NoYes::Yes));

        QueryBuildDataSource securityGroupListDS = warehouseListDS.addDataSource(tableNum(METUserSecurityGroupList));
        securityGroupListDS.joinMode(JoinMode::ExistsJoin);
        securityGroupListDS.relations(false);
        securityGroupListDS.addLink(fieldNum(METUserSecurityWarehouseList, UserSecurityGroupId), fieldNum(METUserSecurityGroupList, UserSecurityGroupId));
        securityGroupListDS.addRange(fieldNum(METUserSecurityGroupList, UserId)).value(queryValue(curUserId()));
    }
}
